import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { tenantColumns } from "./_shared";

/**
 * Directed "blocked by" edges. `issue_id` cannot move to `done` while one of
 * its blocker rows is still open. The pair is unique per organization.
 */
export const issueDependencies = sqliteTable(
  "issue_dependencies",
  {
    ...tenantColumns,
    issueId: text("issue_id").notNull(),
    blockerId: text("blocker_id").notNull(),
    createdBy: text("created_by").notNull(),
    createdAt: text("created_at").notNull(),
  },
  (table) => [
    uniqueIndex("issue_dependencies_pk").on(
      table.orgId,
      table.issueId,
      table.blockerId,
    ),
    index("issue_dependencies_org_blocker_idx").on(table.orgId, table.blockerId),
  ],
);

export type IssueDependencyRow = typeof issueDependencies.$inferSelect;
export type NewIssueDependencyRow = typeof issueDependencies.$inferInsert;

import type { IssueId } from "@/types/common";

/**
 * Open issues just archived by a project cascade. `archiveIssuesForProject`
 * records them and the unblocked handler consumes them when `project.archived`
 * is delivered, so a closed→closed archive never notifies and a second
 * listener cannot deliver the same batch twice.
 */
let pendingArchivedOpenIssueIds: readonly IssueId[] = [];

export function rememberArchivedOpenIssues(ids: readonly IssueId[]): void {
  pendingArchivedOpenIssueIds = ids;
}

export function consumeArchivedOpenIssues(): readonly IssueId[] {
  const ids = pendingArchivedOpenIssueIds;
  pendingArchivedOpenIssueIds = [];
  return ids;
}

/**
 * Blocked-by edges. Every read and write is scoped by `orgId`.
 *
 * Must call (do not reimplement): shouldFilterArchived
 */
import { and, asc, eq, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { brandId, brandStamp, toIssue } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type { IssueDependencyRow } from "@/server/db";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";

function toDependency(row: IssueDependencyRow): IssueDependency {
  return {
    orgId: brandId<OrgId>(row.orgId),
    issueId: brandId<IssueId>(row.issueId),
    blockerId: brandId<IssueId>(row.blockerId),
    createdBy: brandId<UserId>(row.createdBy),
    createdAt: brandStamp(row.createdAt),
  };
}

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toDependency(row) : null;
}

export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<IssueDependency> {
  const row = getDb()
    .insert(issueDependencies)
    .values({
      orgId,
      issueId,
      blockerId,
      createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .returning()
    .get();
  return toDependency(row);
}

/** Resolves `true` when a row was deleted and `false` when there was none. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const rows = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning({ issueId: issueDependencies.issueId })
    .all();
  return rows.length > 0;
}

/** Every edge in the organization, including ones that touch archived issues. */
export async function listEdges(
  orgId: OrgId,
): Promise<readonly { issueId: IssueId; blockerId: IssueId }[]> {
  const rows = getDb()
    .select({
      issueId: issueDependencies.issueId,
      blockerId: issueDependencies.blockerId,
    })
    .from(issueDependencies)
    .where(orgPredicate(issueDependencies.orgId, orgId))
    .all();
  return rows.map((row) => ({
    issueId: brandId<IssueId>(row.issueId),
    blockerId: brandId<IssueId>(row.blockerId),
  }));
}

/**
 * Blockers of `issueId` that are not archived, open or closed, ordered by
 * issue number ascending.
 */
export async function listBlockerIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.blockerId),
        eq(issues.orgId, issueDependencies.orgId),
      ),
    )
    .where(
      and(
        ...compact(
          orgPredicate(issueDependencies.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.issue.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row.issue, (labels[row.issue.id] ?? []).map((label) => label.id)),
  );
}

/** Ids of blockers that are still open (live, and neither done nor canceled). */
export async function listOpenBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ id: issues.id })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.blockerId),
        eq(issues.orgId, issueDependencies.orgId),
      ),
    )
    .where(
      and(
        ...compact(
          orgPredicate(issueDependencies.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          livePredicate(issues.archivedAt, {}),
          notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
  return rows.map((row) => brandId<IssueId>(row.id));
}

/** Issues that list `blockerId` as a blocker, archived and closed included. */
export async function listDependentIssues(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.issueId),
        eq(issues.orgId, issueDependencies.orgId),
      ),
    )
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();
  return rows.map((row) => toIssue(row.issue));
}

