/**
 * Blocked-by links: who may edit them, cycle rejection, and the notification fired when a blocker finally closes.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { consumeArchivedOpenIssues } from "@/server/repositories/_pending-archive";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { Actor } from "@/types/member";

export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;
  readonly blockerIds: readonly IssueId[];

  constructor(blockerIds: readonly IssueId[]) {
    super(`Issue is blocked by open issues: ${blockerIds.join(", ")}`);
    this.name = "IssueBlockedError";
    this.blockerIds = [...blockerIds];
  }
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/**
 * True when adding `issueId → blockerId` would close a loop through existing
 * edges. A self-link is a cycle of length one.
 */
function linkCreatesCycle(
  edges: readonly { issueId: IssueId; blockerId: IssueId }[],
  issueId: IssueId,
  blockerId: IssueId,
): boolean {
  const next = new Map<string, string[]>();
  for (const edge of edges) {
    const list = next.get(edge.issueId) ?? [];
    list.push(edge.blockerId);
    next.set(edge.issueId, list);
  }

  const stack = [blockerId as string];
  const seen = new Set<string>();
  while (stack.length > 0) {
    const current = stack.pop() as string;
    if (seen.has(current)) continue;
    if (current === issueId) return true;
    seen.add(current);
    for (const blocker of next.get(current) ?? []) stack.push(blocker);
  }
  return false;
}

/**
 * Records that `issueId` is blocked by `blockerId`. An existing link is
 * returned as-is. A self-link or a cycle stores nothing.
 */
export async function addBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );

  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  if (input.issueId === input.blockerId) {
    throw new Error("An issue cannot block itself");
  }

  const edges = await dependencyRepo.listEdges(input.orgId);
  if (linkCreatesCycle(edges, input.issueId, input.blockerId)) {
    throw new Error("Blocker link would create a cycle");
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
    actor.userId,
  );
}

/**
 * Removes one blocked-by link. The blocker issue does not have to exist.
 * Resolves `false` when there was no such link.
 */
export async function removeBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

/** Non-archived blockers of `issueId`, ordered by issue number ascending. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockerIssues(orgId, issueId);
}

/**
 * Notifies the assignee of each issue that just lost its last open blocker.
 * One notification per issue; delivery still goes through `notify`, so self
 * actions and muted preferences produce no row.
 */
async function fanOutUnblocked(
  orgId: OrgId,
  blockerIds: readonly IssueId[],
  actorId: UserId | null,
): Promise<void> {
  const notified = new Set<string>();

  for (const blockerId of blockerIds) {
    const dependents = await dependencyRepo.listDependentIssues(orgId, blockerId);
    for (const issue of dependents) {
      if (notified.has(issue.id)) continue;
      if (isArchived(issue) || isClosedStatus(issue.status)) continue;
      if (issue.assigneeId === null) continue;

      const open = await dependencyRepo.listOpenBlockerIds(orgId, issue.id);
      if (open.length > 0) continue;

      notified.add(issue.id);
      await notify(orgId, "issue_unblocked", [issue.assigneeId], {
        title: "Issue unblocked",
        body: "All blocking issues are resolved.",
        href: `/issues/${issue.id}`,
        actorId,
      });
    }
  }
}

/**
 * Reacts to a blocker leaving the open state. Registered from
 * `registerEventHandlers` so the notification exists once that call returns.
 */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", (payload) => {
      const wasOpen = !isClosedStatus(payload.from);
      const nowClosed = isClosedStatus(payload.to);
      if (!wasOpen || !nowClosed) return;
      return fanOutUnblocked(payload.orgId, [payload.issueId], payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (!issue || isClosedStatus(issue.status)) return;
      await fanOutUnblocked(payload.orgId, [payload.issueId], payload.actorId);
    }),
    subscribe("project.archived", (payload) => {
      if (payload.issuesArchived === 0) return;
      const ids = consumeArchivedOpenIssues();
      return fanOutUnblocked(payload.orgId, ids, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

