function isIssueBlockedError(
  error: unknown,
): error is Error & { readonly code: "conflict"; readonly blockerIds: readonly string[] } {
  if (!(error instanceof Error) || error.name !== "IssueBlockedError") return false;
  const candidate = error as Error & { code?: unknown; blockerIds?: unknown };
  return candidate.code === "conflict" && Array.isArray(candidate.blockerIds);
}

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof InvalidSlugError ||
    error instanceof ZodError ||
    isIssueBlockedError(error)
  );
}

