import { TenantScopeError } from "@/lib/tenant";
import { PermissionDeniedError } from "@/lib/permissions";
import { getDb } from "@/server/db";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { NotFoundError } from "@/server/services/_support";
import {
  addBlocker,
  IssueBlockedError,
  listBlockers,
  removeBlocker,
} from "@/server/services/issue-dependency-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("deps");
  other = await createTenant("deps-other");
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

async function makeIssue(
  title: string,
  overrides: Partial<{ assigneeId: Tenant["userIds"]["member"] | null; status: Issue["status"] }> = {},
): Promise<Issue> {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, {
      title,
      assigneeId: overrides.assigneeId === undefined ? tenant.userIds.admin : overrides.assigneeId,
      status: overrides.status,
    }),
  );
}

function linkCount(): number {
  const row = getDb()
    .prepare("SELECT COUNT(*) AS n FROM issue_dependencies")
    .get() as { n: number };
  return row.n;
}

async function unblockedNotes(recipient = tenant.userIds.admin) {
  const rows = getDb()
    .prepare(
      "SELECT kind, href, actor_id AS actorId, recipient_id AS recipientId, title, body FROM notifications WHERE org_id = ? AND recipient_id = ? AND kind = 'issue_unblocked'",
    )
    .all(tenant.org.id, recipient) as {
    kind: string;
    href: string;
    actorId: string | null;
    recipientId: string;
    title: string;
    body: string;
  }[];
  return rows;
}

describe("issue dependencies", () => {
  it("links, lists by number, and is idempotent", async () => {
    const blocked = await makeIssue("Blocked alpha");
    const first = await makeIssue("Blocker one");
    const second = await makeIssue("Blocker two");
    const before = linkCount();

    const link = await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: second.id,
    });
    expect(link.createdBy).toBe(tenant.userIds.member);
    expect(link.issueId).toBe(blocked.id);
    expect(link.blockerId).toBe(second.id);

    const again = await addBlocker(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: second.id,
    });
    expect(again.createdAt).toBe(link.createdAt);
    expect(again.createdBy).toBe(link.createdBy);
    expect(linkCount()).toBe(before + 1);

    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: first.id,
    });

    const listed = await listBlockers(tenant.actors.viewer, tenant.org.id, blocked.id);
    expect(listed.map((issue) => issue.id)).toEqual([first.id, second.id]);
    expect(listed.map((issue) => issue.number)).toEqual(
      [...listed].sort((a, b) => a.number - b.number).map((issue) => issue.number),
    );
  });

  it("rejects self, direct cycle, and chain cycle without storing", async () => {
    const a = await makeIssue("Cycle A");
    const b = await makeIssue("Cycle B");
    const c = await makeIssue("Cycle C");
    const before = linkCount();

    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: a.id,
        blockerId: a.id,
      }),
    ).rejects.toThrow(/itself/);
    expect(linkCount()).toBe(before);

    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: a.id,
      blockerId: b.id,
    });
    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: b.id,
        blockerId: a.id,
      }),
    ).rejects.toThrow(/cycle/);

    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: b.id,
      blockerId: c.id,
    });
    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: c.id,
        blockerId: a.id,
      }),
    ).rejects.toThrow(/cycle/);
    expect(linkCount()).toBe(before + 2);
  });

  it("rejects archived endpoints, foreign orgs, missing ids, and viewers", async () => {
    const live = await makeIssue("Perm live");
    const otherIssue = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Other org issue" }),
    );
    const archived = await makeIssue("Will archive");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);
    const before = linkCount();

    await expect(
      addBlocker(tenant.actors.member, {
        orgId: other.org.id,
        issueId: live.id,
        blockerId: live.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: otherIssue.id,
        blockerId: live.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: live.id,
        blockerId: archived.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: archived.id,
        blockerId: live.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      addBlocker(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: live.id,
        blockerId: live.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    expect(linkCount()).toBe(before);
  });

  it("removes a link only when it exists and does not require the blocker", async () => {
    const blocked = await makeIssue("Remove me");
    const blocker = await makeIssue("Remove blocker");
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: blocker.id,
    });

    expect(
      await removeBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        blockerId: blocker.id,
      }),
    ).toBe(true);
    expect(
      await removeBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        blockerId: blocker.id,
      }),
    ).toBe(false);
    expect(
      await removeBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        blockerId: "missing-blocker" as Issue["id"],
      }),
    ).toBe(false);

    await expect(
      removeBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: "missing-issue" as Issue["id"],
        blockerId: blocker.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses done while an open blocker remains and allows other statuses", async () => {
    const blocked = await makeIssue("Gate target", { assigneeId: tenant.userIds.member });
    const open = await makeIssue("Open blocker");
    const done = await makeIssue("Done blocker");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: done.id,
      status: "done",
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: open.id,
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: done.id,
    });

    const seen: unknown[] = [];
    const off = subscribe("issue.status_changed", (payload) => {
      seen.push(payload);
    });
    try {
      await expect(
        issueService.changeIssueStatus(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: blocked.id,
          status: "done",
        }),
      ).rejects.toMatchObject({
        name: "IssueBlockedError",
        code: "conflict",
        blockerIds: [open.id],
      });
      await expect(
        issueService.moveIssue(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: blocked.id,
          toStatus: "done",
          toIndex: 0,
        }),
      ).rejects.toBeInstanceOf(IssueBlockedError);
    } finally {
      off();
    }

    expect(seen).toHaveLength(0);
    const stored = await issueRepo.findIssueById(tenant.org.id, blocked.id);
    expect(stored?.status).toBe("backlog");

    const canceled = await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      status: "canceled",
    });
    expect(canceled.status).toBe("canceled");
  });

  it("notifies once when the last open blocker closes, and not on closed-to-closed", async () => {
    const blocked = await makeIssue("Notify target", { assigneeId: tenant.userIds.admin });
    const blocker = await makeIssue("Notify blocker", { assigneeId: tenant.userIds.member });
    const extra = await makeIssue("Still open", { assigneeId: tenant.userIds.member });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: blocker.id,
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: extra.id,
    });

    await issueService.changeIssueStatus(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: blocker.id,
      status: "done",
    });
    expect(await unblockedNotes()).toHaveLength(0);

    await issueService.changeIssueStatus(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: extra.id,
      status: "canceled",
    });
    let notes = await unblockedNotes();
    expect(notes).toHaveLength(1);
    expect(notes[0]?.href).toBe(`/issues/${blocked.id}`);
    expect(notes[0]?.actorId).toBe(tenant.userIds.owner);

    await issueService.changeIssueStatus(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: extra.id,
      status: "done",
    });
    expect(await unblockedNotes()).toHaveLength(1);

    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, extra.id);
    expect(await unblockedNotes()).toHaveLength(1);
  });

  it("notifies on archive of an open blocker and again after reopen", async () => {
    const blocked = await makeIssue("Archive notify", { assigneeId: tenant.userIds.admin });
    const blocker = await makeIssue("Archive blocker");
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: blocker.id,
    });
    const before = (await unblockedNotes()).length;
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, blocker.id);
    const notes = await unblockedNotes();
    expect(notes.length).toBe(before + 1);
    expect(notes.at(-1)?.actorId).toBe(tenant.userIds.member);

    const closed = await makeIssue("Already done blocker");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: closed.id,
      status: "done",
    });
    const waiting = await makeIssue("Waiting on closed", { assigneeId: tenant.userIds.admin });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: waiting.id,
      blockerId: closed.id,
    });
    const mid = (await unblockedNotes()).length;
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, closed.id);
    expect(await unblockedNotes()).toHaveLength(mid);
  });

  it("does not notify the actor, a muted recipient, or on link removal", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "issue_unblocked",
      inApp: false,
      email: false,
      digestOnly: false,
    });

    const self = await makeIssue("Self assigned", { assigneeId: tenant.userIds.member });
    const selfBlocker = await makeIssue("Self blocker");
    await addBlocker(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: self.id,
      blockerId: selfBlocker.id,
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: selfBlocker.id,
      status: "done",
    });
    expect(await unblockedNotes(tenant.userIds.member)).toHaveLength(0);

    const muted = await makeIssue("Muted assignee", { assigneeId: tenant.userIds.viewer });
    const mutedBlocker = await makeIssue("Muted blocker");
    await addBlocker(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: muted.id,
      blockerId: mutedBlocker.id,
    });
    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: mutedBlocker.id,
      status: "done",
    });
    expect(await unblockedNotes(tenant.userIds.viewer)).toHaveLength(0);

    const kept = await makeIssue("Remove link", { assigneeId: tenant.userIds.admin });
    const keptBlocker = await makeIssue("Remove link blocker");
    await addBlocker(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: kept.id,
      blockerId: keptBlocker.id,
    });
    const before = (await unblockedNotes()).length;
    await removeBlocker(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: kept.id,
      blockerId: keptBlocker.id,
    });
    expect(await unblockedNotes()).toHaveLength(before);
  });

  it("notifies again when a blocker is reopened and closed", async () => {
    const blocked = await makeIssue("Reopen target", { assigneeId: tenant.userIds.admin });
    const blocker = await makeIssue("Reopen blocker");
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: blocker.id,
    });
    await issueService.changeIssueStatus(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: blocker.id,
      status: "done",
    });
    const once = (await unblockedNotes()).length;
    await issueService.changeIssueStatus(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: blocker.id,
      status: "in_progress",
    });
    expect(await unblockedNotes()).toHaveLength(once);
    await issueService.changeIssueStatus(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: blocker.id,
      status: "done",
    });
    expect(await unblockedNotes()).toHaveLength(once + 1);
  });

  it("notifies when a project cascade archives an open blocker", async () => {
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Cascade deps",
      slug: "cascade-deps",
      key: "CDP",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const blocker = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, project.id, { title: "Cascaded blocker" }),
    );
    const also = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, project.id, { title: "Cascaded too" }),
    );
    const blocked = await makeIssue("Outside cascade", { assigneeId: tenant.userIds.admin });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: blocker.id,
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: also.id,
    });
    const before = (await unblockedNotes()).length;
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: true,
    });
    const notes = await unblockedNotes();
    expect(notes.length).toBe(before + 1);
    expect(notes.at(-1)?.href).toBe(`/issues/${blocked.id}`);
    expect(notes.at(-1)?.actorId).toBe(tenant.userIds.admin);
  });

  it("accepts issue_unblocked in the preference schema", async () => {
    const saved = await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "issue_unblocked",
      inApp: true,
      email: false,
      digestOnly: false,
    });
    expect(saved.kind).toBe("issue_unblocked");
    expect(saved.email).toBe(false);
  });
});

