import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { IssueStatus } from "@/types/issue";

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/**
 * One `issue_unblocked` row per dependent that is still open, has an assignee,
 * and has no open blocker left. `notify` drops self-actions and muted kinds.
 */
async function fanOutUnblocked(
  orgId: OrgId,
  blockerIds: readonly IssueId[],
  actorId: UserId | null,
): Promise<void> {
  const notified = new Set<string>();

  for (const blockerId of blockerIds) {
    const dependents = await dependencyRepo.listDependentIssues(orgId, blockerId);
    for (const issue of dependents) {
      if (notified.has(issue.id)) continue;
      if (isArchived(issue) || isClosedStatus(issue.status)) continue;
      if (issue.assigneeId === null) continue;

      const open = await dependencyRepo.listOpenBlockerIds(orgId, issue.id);
      if (open.length > 0) continue;

      notified.add(issue.id);
      await notify(orgId, "issue_unblocked", [issue.assigneeId], {
        title: "Issue unblocked",
        body: "All blocking issues are resolved.",
        href: `/issues/${issue.id}`,
        actorId,
      });
    }
  }
}

export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", (payload) => {
      const wasOpen = !isClosedStatus(payload.from);
      const nowClosed = isClosedStatus(payload.to);
      if (!wasOpen || !nowClosed) return;
      return fanOutUnblocked(payload.orgId, [payload.issueId], payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (!issue || isClosedStatus(issue.status)) return;
      await fanOutUnblocked(payload.orgId, [payload.issueId], payload.actorId);
    }),
    subscribe("project.archived", (payload) => {
      if (payload.issuesArchived === 0) return;
      const ids = consumeArchivedOpenIssues();
      return fanOutUnblocked(payload.orgId, ids, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

